data_structures.source:
@slotted_freezable
@dataclass
class Account:
    nonce: Uint
    balance: U256
    code: Bytes

functions.source:
def encode_account(raw_account_data: Account, storage_root: Bytes) -> Bytes:
    return rlp.encode(
        (
            raw_account_data.nonce,
            raw_account_data.balance,
            storage_root,
            keccak256(raw_account_data.code),
        )
    )

